def render_report_header(template: str, report: dict) -> str:
    """
    একটি টেমপ্লেট ব্যবহার করে একটি রিপোর্ট শিরোনামের জন্য HTML রিটার্ন করে।

    :param template: HTML রিটার্ন করার জন্য টেমপ্লেট।
    :param report: রিপোর্ট ডেটা।
    :return: HTML রিটার্ন করে।
    """
    html = ""
    for key, value in report.items():
        html += f"<h1>{key}</h1>"
        if isinstance(value, list):
            html += "<p>List of values: "
            for item in value:
                html += f"<li>{item}</li>"
            html += "</p>"
        elif isinstance(value, dict):
            html += "<p>Values for key: "
            for key, value in value.items():
                html += f"<li>{key}: {value}</li>"
            html += "</p>"
        else:
            html += f"<li>{key}: {value}</li>"
    return html

