def longest_bitonic_length(nums: list[int]) -> int:
    n = len(nums)
    if n == 1:
        return 1
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        dp[i] = dp[i - 1] + 1
        for j in range(i - 1, -1, -1):
            if nums[j] == nums[j + 1] and dp[j] + 1 > dp[j + 1]:
                dp[j + 1] = dp[j] + 1
    return max(dp)

