def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        return []

    # প্রতিটি কলামের জন্য গড় হিসাব করুন
    mean = sum(nums) / k

    # প্রতিটি কলামের জন্য গড় হিসাব করুন
    variances = []
    for i in range(k, len(nums)):
        variances.append(round((nums[i] - mean)**2 / k, 3))

    return variances

def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        return []

    mean = sum(nums) / k

    variances = []
    for i in range(k, len(nums)):
        sq_diff = (nums[i] - mean) ** 2
        variances.append(round(sq_diff / k, 3))

    return variances

def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        return []

    mean = sum(nums) / k

    variances = []
    for i in range(k, len(nums)):
        sq_diff = (nums[i] - mean) ** 2
        variances.append(round(sq_diff / (k - 1)))

    return variances

