def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'

    result = ''
    while n > 0:
        remainder = n % 3
        if remainder == 1:
            result = '1' + result
        elif remainder == 2:
            result = '2' + result
        else:
            result = '0' + result
        n //= 3

    return result

