def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    """
    এই ফাংশনটি একটি তালিকা গ্রহণ করে যেখানে প্রতিটি টুপল একটি কাজের নাম, সময়সীমা, এবং লাভ ধারণ করে।
    প্রতিটি কাজের জন্য, এটি নির্ধারণ করে যে কোন কাজটি নির্দিষ্ট সময়সীমার মধ্যে শেষ হওয়া সম্ভব কিনা।
    যদি কোনও কাজ নির্দিষ্ট সময়সীমার মধ্যে শেষ না হয়, তবে এটি সেই সময়সীমাটি উপেক্ষা করে।
    ফাংশনটি তারপর কাজের তালিকা দিয়ে লুপ চালায় এবং সর্বোচ্চ নম্বরযুক্ত কাজটি খুঁজে বের করে যা নির্দিষ্ট সময়সীমার মধ্যে শেষ হওয়া সম্ভব।
    যদি কোনও এমন কাজ পাওয়া না যায়, তবে এটি ব্যবহার্য সময়সীমা উপেক্ষা করে।
    অবশেষে, এটি কাজগুলোর নাম, সময়সীমা, এবং লাভ অনুযায়ী সাজিয়ে একটি তালিকা ফেরত দেয়।
    """
    scheduled_jobs = []
    for job in jobs:
        name, deadline, profit = job
        if deadline <= 0:
            continue
        if deadline <= deadline[0]:
            scheduled_jobs.append(name)
        else:
            for i in range(deadline[0]):
                if i <= deadline[1]:
                    scheduled_jobs.append(name)
                    break
    return sorted(scheduled_jobs, key=lambda x: x[1], reverse=True)

