import requests

def download_text(url: str, attempts: int = 3) -> str | None:
    """
    একটি ডকুমেন্ট ডাউনলোড করে টেক্সট।

    :param url: ডাউনলোড করার জন্য URL
    :param attempts: কতবার চেষ্টা করবেন
    :return: ডাউনলোড করা টেক্সট
    """
    if requests.get(url, timeout=5) is None:
        return None

    for attempt in range(1, attempts + 1):
        try:
            response = requests.get(url, timeout=5)
            if response.status_code == 404:
                return None
            elif response.status_code >= 400:
                raise requests.HTTPError(response.status_code)
            else:
                return response.text
        except requests.ConnectionError:
            if attempt == attempts:
                raise requests.HTTPError(response.status_code)
            else:
                return download_text(url, attempts)
    return None

