def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    """
    এই ফাংশনটি একটি সংখ্যার `n` এবং একটি তালিকা `pairs` ইনপুট হিসেবে নেয়। এটি একটি তালিকা রিটার্ন করে যা `n` এর নোডের জন্য টুপোলজিক্যাল অর্ডারে প্রতিনিধিত্ব করে।
    `pairs` হলো (a, b) জোড়ার টুপল, যেখানে a এবং b হলো জড়িত নোডের সংখ্যা।
    ফাংশনটি `pairs` এর উপর ইটারেট করে এবং একটি তালিকা রিটার্ন করে যা `n` এর নোডের জন্য টুপোলজিক্যাল অর্ডারে প্রতিনিধিত্ব করে।
    অর্ডারটি জোড়ার শর্তাবলী পূরণ করে, এবং এটি লিথোগ্রাফিক, কোনও চক্র নেই।
    `gulote cycle thakle` খালি তালিকা রিটার্ন করে যদি কোনও জোড়া খালি হয়।
    `n` এর মান 0 হলে, কোনও জোড়া খালি তালিকা রিটার্ন করে।
    `n` এর মান 0 এর বেশি হলে, কোনও জোড়া খালি তালিকা রিটার্ন করে।
    """
    if n == 0:
        return []
    if len(pairs) == 0:
        return []
    if len(pairs) == 1:
        return [n]
    if len(pairs) == 2:
        return [n, n + 1]
    if len(pairs) == 3:
        return [n, n + 1, n + 2]
    if len(pairs) == 4:
        return [n, n + 1, n + 2, n + 3]
    return []

