def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    """
    এই ফাংশনটি একটি তালিকা গ্রহণ করে যেখানে প্রতিটি টুপল একটি টাস্ক এবং তার অর্ডার উপস্থাপন করে। এটি একটি স্ট্যাক ব্যবহার করে টাস্কের ক্রম ট্র্যাক করে। যদি একটি টাস্ক ইতিমধ্যে স্ট্যাকে থাকে, তবে সেটি বাদ দেওয়া হয়। যদি একটি টাস্ক পূর্বের টাস্কের আগে আসে, তবে এটি ক্রমের মধ্যে যোগ করা হয়। অবশেষে, এটি স্ট্যাকে থাকা টাস্কের ক্রমটি ফেরত দেয়, যা প্রদত্ত `pairs` তালিকার শর্ত অনুযায়ী এবং লিনিয়ারভাবে ক্ষুদ্রতম।

    যদি `pairs` তালিকাটি খালি হয়, তবে এটি একটি খালি তালিকা ফেরত দেয়। যদি `n` শূন্য হয়, তবে এটি একটি খালি তালিকা ফেরত দেয়।

    """
    stack = []
    order = []

    for task, order_num in pairs:
        if len(stack) == 0 or stack[-1] != order_num:
            stack.append(task)
        else:
            order.append(stack.pop())

    return order

