    if n == 0:
        return []

    stack = []
    order = []

    for i in range(n):
        if len(stack) == 0 or stack[-1][1] < pairs[stack[-1][0]][0]:
            stack.append((n, pairs[stack[-1][0]][0]))
        else:
            order.append(stack.pop()[1])

