def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    result = []
    for i in range(1 << len(nums)):
        subset = []
        for j in range(len(nums)):
            if (i >> j) & 1:
                subset.append(nums[j])
        if len(subset) == 0:
            continue
        if sum(subset) == k:
            result.append(subset)
        elif sum(subset) < k:
            continue
        elif sum(subset) > k:
            result.append(descending_subset(subset))
    return result

def descending_subset(nums: list[int]) -> list[int]:
    result = []
    for i in range(len(nums)):
        subset = nums[i:]
        if len(subset) == 0:
            continue
        if sum(subset) == k:
            result.append(subset)
        elif sum(subset) < k:
            continue
        elif sum(subset) > k:
            result.append(subset[::-1])
    return result

