def charge_card(card_number: str, amount_cents: int, gateway) -> str:
    """
    একটি পেমেন্ট কার্ড চার্জ করে একটি পেমেন্ট গেটওয়ে ব্যবহার করে এবং ফলাফলটি standard `logging` মডিউলের মাধ্যমে নিবন্ধন করে। এটি `gateway(card_number, amount_cents)`, একটি ফাংশন প্রদান করে যা Who Calls that returns the transaction identifier as a `str`, এবং সেই স্ট্রিংটি রিটার্ন করে। একটি সফল কল হলে, এটি একটি log entry তৈরি করে যার লেভেল `INFO` যার বার্তা содержит transaction identifier এবং amount_cents মানটি একটি সহজ দশমিক সংখ্যা (উদাহরণস্বরূপ `1999`) হিসেবে লেখা। যদি `gateway` একটি `ValueError` ছুঁড়ে, তবে এটি একটি log entry তৈরি করে যার লেভেল `WARNING` যার বার্তা содержит amount_cents মানটি একটি সহজ দশমিক সংখ্যা এবং `declined` শব্দটি। এবং তারপর, এটি সেই `ValueError` কে প্রসেস করে।

    ফেরত দেয় শুধুমাত্র সম্পূর্ণ কোডটি একটি একক ব্লকে, Python এ।
    """
    try:
        transaction_id = gateway(card_number, amount_cents)
        log.info(f'Transaction ID: {transaction_id}')
        return log.format_log(transaction_id)
    except ValueError:
        log.warning(f'Declined: {amount_cents}')
        return log.format_log(amount_cents)

