def render_report_header(template: str, report: dict) -> str:
    """
    একটি নির্দিষ্ট টেমপ্লেট দিয়ে টুপলের মানগুলি দিয়ে রাউটিং করে, যেখানে টুপলের মানগুলি
    প্রদত্ত টেমপ্লেটের মধ্যে নির্দিষ্ট কীগুলির জন্য মান হিসেবে ব্যবহৃত হয়।
    """
    for key in report:
        if key in report:
            value = report[key]
            if isinstance(value, str):
                value = value.replace(' ', '_')
            if key not in template:
                template = template.replace(key, '{{ ' + key + ' }}')
            template = template.replace(key, value)
        else:
            template = template.replace(key, '{{ ' + key + ' }}')
    return template

