    """
    final_balances = {}
    failed = []
    for op in ops:
        if op[0] == 'deposit':
            final_balances[op[1]] = op[2]
        elif op[0] == 'withdraw':
            final_balances[op[1]] = op[2]
        elif op[0] == 'transfer':
            final_balances[op[1]] = op[2]
        elif op[0] == 'freeze':
            final_balances[op[1]] = op[2]
        elif op[0] == 'unfreeze':
            final_balances[op[1]] = op[2]
        else:
            failed.append(op[1])
    return final_balances, failed

