    উদাহরণ: `x` যখন `2`, তখন `x**2 + 3*x` থেকে `10.0` পাওয়া যায়, আর `x` যখন `16`, তখন `sqrt(x) + 1` থেকে `5.0` পাওয়া যায়। শূন্য দিয়ে ভাগ করলে `ZeroDivisionError` ওঠে।

    শুধু সম্পূর্ণ কোডটি একটি পাইথন কোড ব্লকে দিন।
    """
    try:
        # ফাংশনটি পরীক্ষা করুন
        if 'sqrt' in formula or 'abs' in formula or 'sin' in formula or 'cos' in formula:
            return float(formula)
        else:
            # ফাংশনটি পরীক্ষা করুন
            if 'x' in formula or '0.5' in formula:
                return float(formula)
            else:
                raise ValueError("Invalid formula")
    except ValueError:
        return float(formula)

