def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        if instruction == 'PUSH':
            stack.append(int(instruction.split()[1]))
        elif instruction == 'POP':
            if len(stack) > 0:
                stack.pop()
        elif instruction == 'DUP':
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) > 1:
                stack.pop()
                stack.pop()
                stack.append(stack[-1])
        elif instruction == 'ADD':
            if len(stack) > 1:
                stack.pop()
                stack.append(stack[-1])
        elif instruction == 'SUB':
            if len(stack) > 1:
                stack.pop()
                stack.append(stack[-1])
        elif instruction == 'MUL':
            if len(stack) > 1:
                stack.pop()
                stack.append(stack[-1])
        elif instruction == 'JMP':
            if len(stack) > 0:
                if stack[-1] == 0:
                    stack.pop()
                else:
                    stack.append(stack[-1])
            else:
                stack.append(stack[-1])
        elif instruction == 'JZ':
            if len(stack) > 1:
                if stack[-1] == 0:
                    stack.pop()
                else:
                    stack.append(stack[-1])
            else:
                stack.append(stack[-1])
        elif instruction == 'HALT':
            break
        else:
            raise ValueError(instruction)
    return stack

