def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append(v)
        graph[v].append(u)

    shortest_paths = []
    for node in graph:
        shortest_path = []
        for neighbor in graph[node]:
            path = [source, node, neighbor]
            if len(shortest_path) == 1:
                shortest_path.append(path)
            else:
                for i in range(len(shortest_path) - 1):
                    path = shortest_path[i] + "->" + shortest_path[i+1]
                    if len(path) == 3 and path[0] == source and path[1] == node and path[2] == neighbor:
                        shortest_path.append(path)
        if len(shortest_path) >= 1:
            shortest_paths.append(shortest_path)

    return len(shortest_paths)
```

